window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6c16b055b49d7eb6"]={"versions": [{"id": "FIG-6c16b055b49d7eb6", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Botschaftsablaufdiagramm zur Netzwerkmanagement-Kommunikation im AUTOSAR-CAN-Stack. Das Diagramm illustriert das koordinierte Sende- und Empfangsverhalten mehrerer Steuergeräte (ECU 1, 2 und 3) auf einem gemeinsamen CAN-Bus beim Übergang und Betrieb im Zustand Repeat Message State (RM) unter Berücksichtigung der Buslastreduktion (Bus Load Reduction).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten / Instanzen</strong>: Drei Steuergeräte (ECUs), repräsentiert durch die farbigen Kreis-Indikatoren <code>1</code> (grün), <code>2</code> (blau) und <code>3</code> (gelb) inklusive jeweiliger Zeitstrahlen und Sendeblöcke.</li>\n<li><strong>Zustandsindikatoren</strong>:</li>\n<li><code>RM</code>: Repeat Message State.</li>\n<li>Legende: <code>NO</code> = Normal Operation, <code>RS</code> = Ready Sleep.</li>\n<li><strong>Ereignisse & Timer-Trigger (Restart of the NM-Timeout Timer)</strong>:</li>\n<li>Gefüllter Kreis: Neustart des NM-Timeout-Timers bei erfolgreicher Sendebestätigung (<code>at NM-Msg Tx Conf</code>).</li>\n<li>Ungefüllter Kreis: Neustart des NM-Timeout-Timers bei Empfangsanzeige einer NM-Botschaft (<code>at NM-Msg Rx Ind</code>).</li>\n<li><strong>Funktionsschnittstellen / Trigger-Aufrufe</strong>:</li>\n<li><code>(1,2,3): Nm_StopBusLoadReduction()</code> bzw. <code>Nm_StartTransmission()</code> als auslösende Funktionsaufrufe über dem Zeitstrahl.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zu Beginn erfolgt für die Steuergeräte (1, 2, 3) die Aufhebung der Buslastreduktion bzw. der Sendestart (<code>Nm_StopBusLoadReduction(); Nm_StartTransmission();</code>).</li>\n<li>Alle drei ECUs befinden sich im <code>RM</code> (Repeat Message State) und senden zyklisch NM-Botschaften (dargestellt als farbige Balken auf dem Bus für ECU 1, ECU 2 und ECU 3).</li>\n<li>Sobald eine ECU ihre eigene NM-Botschaft erfolgreich sendet, führt die Sendebestätigung (<code>NM-Msg Tx Conf</code>, gefüllter Kreis) zum Zurücksetzen/Neustart des lokalen NM-Timeout-Timers.</li>\n<li>Die jeweils anderen ECUs empfangen diese Botschaft auf dem gemeinsamen Bus, woraufhin deren lokaler NM-Timeout-Timer durch die Empfangsanzeige (<code>NM-Msg Rx Ind</code>, ungefüllter Kreis) neu gestartet wird.</li>\n<li>Dieser Zyklus wiederholt sich über die Zeitachse, wodurch alle beteiligten Knoten gegenseitig durch das alternierende Auftreten von Tx- und Rx-Ereignissen wachgehalten werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient dem Entwicklungs- und Integrationsverständnis des AUTOSAR CAN Network Management (CanNm) Protokolls. Es visualisiert normativ relevante Vorgaben zur Überwachung des NM-Timeout-Timers: Der Timer muss sowohl bei eigener Sendebestätigung (<code>CanNm_TxConfirmation</code>) als auch beim Empfang einer netzwerkweiten NM-PDU (<code>CanNm_RxIndication</code>) zurückgesetzt werden. Dadurch wird verhindert, dass Knoten vorzeitig in den <code>Ready Sleep State</code> übergehen oder Timeouts auslösen, solange ein aktiver Knotenaustausch im Buscluster stattfindet.</p>"}, {"id": "FIG-8a24be09a6ffac58", "releases": ["R20-11", "R21-11", "R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Botschaftsablaufdiagramm zur Netzwerkmanagement-Kommunikation im AUTOSAR-CAN-Stack. Das Diagramm illustriert das koordinierte Sende- und Empfangsverhalten mehrerer Steuergeräte (ECU 1, 2 und 3) auf einem gemeinsamen CAN-Bus beim Übergang und Betrieb im Zustand Repeat Message State (RM) unter Berücksichtigung der Buslastreduktion (Bus Load Reduction).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten / Instanzen</strong>: Drei Steuergeräte (ECUs), repräsentiert durch die farbigen Kreis-Indikatoren <code>1</code> (grün), <code>2</code> (blau) und <code>3</code> (gelb) inklusive jeweiliger Zeitstrahlen und Sendeblöcke.</li>\n<li><strong>Zustandsindikatoren</strong>:</li>\n<li><code>RM</code>: Repeat Message State.</li>\n<li>Legende: <code>NO</code> = Normal Operation, <code>RS</code> = Ready Sleep.</li>\n<li><strong>Ereignisse & Timer-Trigger (Restart of the NM-Timeout Timer)</strong>:</li>\n<li>Gefüllter Kreis: Neustart des NM-Timeout-Timers bei erfolgreicher Sendebestätigung (<code>at NM-Msg Tx Conf</code>).</li>\n<li>Ungefüllter Kreis: Neustart des NM-Timeout-Timers bei Empfangsanzeige einer NM-Botschaft (<code>at NM-Msg Rx Ind</code>).</li>\n<li><strong>Funktionsschnittstellen / Trigger-Aufrufe</strong>:</li>\n<li><code>(1,2,3): Nm_StopBusLoadReduction()</code> bzw. <code>Nm_StartTransmission()</code> als auslösende Funktionsaufrufe über dem Zeitstrahl.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Zu Beginn erfolgt für die Steuergeräte (1, 2, 3) die Aufhebung der Buslastreduktion bzw. der Sendestart (<code>Nm_StopBusLoadReduction(); Nm_StartTransmission();</code>).</li>\n<li>Alle drei ECUs befinden sich im <code>RM</code> (Repeat Message State) und senden zyklisch NM-Botschaften (dargestellt als farbige Balken auf dem Bus für ECU 1, ECU 2 und ECU 3).</li>\n<li>Sobald eine ECU ihre eigene NM-Botschaft erfolgreich sendet, führt die Sendebestätigung (<code>NM-Msg Tx Conf</code>, gefüllter Kreis) zum Zurücksetzen/Neustart des lokalen NM-Timeout-Timers.</li>\n<li>Die jeweils anderen ECUs empfangen diese Botschaft auf dem gemeinsamen Bus, woraufhin deren lokaler NM-Timeout-Timer durch die Empfangsanzeige (<code>NM-Msg Rx Ind</code>, ungefüllter Kreis) neu gestartet wird.</li>\n<li>Dieser Zyklus wiederholt sich über die Zeitachse, wodurch alle beteiligten Knoten gegenseitig durch das alternierende Auftreten von Tx- und Rx-Ereignissen wachgehalten werden.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient dem Entwicklungs- und Integrationsverständnis des AUTOSAR CAN Network Management (CanNm) Protokolls. Es visualisiert normativ relevante Vorgaben zur Überwachung des NM-Timeout-Timers: Der Timer muss sowohl bei eigener Sendebestätigung (<code>CanNm_TxConfirmation</code>) als auch beim Empfang einer netzwerkweiten NM-PDU (<code>CanNm_RxIndication</code>) zurückgesetzt werden. Dadurch wird verhindert, dass Knoten vorzeitig in den <code>Ready Sleep State</code> übergehen oder Timeouts auslösen, solange ein aktiver Knotenaustausch im Buscluster stattfindet.</p>"}], "trans": [{"from": "FIG-6c16b055b49d7eb6", "to": "FIG-8a24be09a6ffac58", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
